package com.dawnrise.school.announcement;
import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/published-announcements") @PreAuthorize("@schoolTenantSecurity.hasOrganization(authentication)") public class TenantAnnouncementController {private final SchoolAnnouncementService service;private final NotificationRecipientAccess access;public TenantAnnouncementController(SchoolAnnouncementService service,NotificationRecipientAccess access){this.service=service;this.access=access;}@GetMapping("/{id}")public AnnouncementDtos.View get(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){long org=((Number)jwt.getClaim("organizationId")).longValue();long user=Long.parseLong(jwt.getSubject());if(!access.allowed(org,user,"ANNOUNCEMENT",id))throw new com.dawnrise.school.school.exception.ResourceNotFoundException("Announcement not found");return service.getPublished(org,id);}}
